def transform(grid):
    H = len(grid)
    W = len(grid[0])

    # Extract section marker rows (uniform non-background rows)
    all_markers = []
    for r in range(H):
        if r == 0:
            continue
        if all(grid[r][c] == grid[r][1] for c in range(W-1, 0, -1)):
            all_markers.append(grid[r][0])

    # Return first 9 values as output
    return all_markers[:9]

